const { Window } = require('happy-dom');
const { setWorldConstructor, setDefaultTimeout } = require('@cucumber/cucumber');
const fs = require('fs');
const path = require('path');

setDefaultTimeout(10000);

function TodoMVCWorld() {
  this.window = null;
  this.document = null;
  this.localStorage = null;
  this.todoIdCounter = 0;
}

TodoMVCWorld.prototype.createWindow = function () {
  const window = new Window();
  const document = window.document;

  // Polyfill localStorage
  const store = {};
  window.localStorage = {
    getItem: (key) => store[key] !== undefined ? store[key] : null,
    setItem: (key, value) => { store[key] = String(value); },
    removeItem: (key) => { delete store[key]; },
    clear: () => { Object.keys(store).forEach(k => delete store[k]); },
    get length() { return Object.keys(store).length; },
    key: (i) => Object.keys(store)[i] || null,
  };

  this.window = window;
  this.document = document;
  this.localStorage = window.localStorage;
  this.todoIdCounter = 0;
};

TodoMVCWorld.prototype.loadAppHTML = function () {
  // Set up the TodoMVC HTML structure
  this.document.body.innerHTML = `
    <section class="todoapp">
      <header class="header">
        <h1>todos</h1>
        <input class="new-todo" placeholder="What needs to be done?" autofocus>
      </header>
      <section class="main">
        <input id="toggle-all" class="toggle-all" type="checkbox">
        <label for="toggle-all">Mark all as complete</label>
        <ul class="todo-list"></ul>
      </section>
      <footer class="footer">
        <span class="todo-count"><strong>0</strong> item left</span>
        <ul class="filters">
          <li><a class="selected" href="#/">All</a></li>
          <li><a href="#/active">Active</a></li>
          <li><a href="#/completed">Completed</a></li>
        </ul>
        <button class="clear-completed">Clear completed</button>
      </footer>
    </section>
  `;
};

TodoMVCWorld.prototype.getTodoItems = function () {
  return this.document.querySelectorAll('.todo-list li');
};

TodoMVCWorld.prototype.findTodoLi = function (title) {
  const items = this.getTodoItems();
  for (const li of items) {
    const label = li.querySelector('label');
    if (label && label.textContent === title) return li;
  }
  return null;
};

TodoMVCWorld.prototype.getTodos = function () {
  try {
    const data = this.localStorage.getItem('todos-vanilla');
    return data ? JSON.parse(data) : [];
  } catch (e) {
    return [];
  }
};

TodoMVCWorld.prototype.saveTodos = function (todos) {
  this.localStorage.setItem('todos-vanilla', JSON.stringify(todos));
};

TodoMVCWorld.prototype.addTodoToStorage = function (title, completed) {
  const todos = this.getTodos();
  const todo = {
    id: String(++this.todoIdCounter),
    title: title,
    completed: completed || false,
  };
  todos.push(todo);
  this.saveTodos(todos);
  return todo;
};

TodoMVCWorld.prototype.renderTodos = function () {
  const todoList = this.document.querySelector('.todo-list');
  const todos = this.getTodos();
  const hash = this.window.location.hash || '#/';
  const filter = hash === '#/active' ? 'active' : hash === '#/completed' ? 'completed' : 'all';

  todoList.innerHTML = '';
  let filteredTodos = todos;
  if (filter === 'active') filteredTodos = todos.filter(t => !t.completed);
  else if (filter === 'completed') filteredTodos = todos.filter(t => t.completed);

  for (const todo of filteredTodos) {
    const li = this.document.createElement('li');
    if (todo.completed) li.classList.add('completed');

    li.innerHTML = `
      <div class="view">
        <input class="toggle" type="checkbox" ${todo.completed ? 'checked' : ''}>
        <label>${todo.title}</label>
        <button class="destroy"></button>
      </div>
      <input class="edit" value="${todo.title}">
    `;
    todoList.appendChild(li);
  }

  this.updateFooter();
};

TodoMVCWorld.prototype.updateFooter = function () {
  const todos = this.getTodos();
  const main = this.document.querySelector('.main');
  const footer = this.document.querySelector('.footer');
  const clearBtn = this.document.querySelector('.clear-completed');
  const todoCount = this.document.querySelector('.todo-count');
  const toggleAll = this.document.querySelector('.toggle-all');

  const activeCount = todos.filter(t => !t.completed).length;
  const completedCount = todos.filter(t => t.completed).length;

  // Show/hide main and footer
  main.style.display = todos.length === 0 ? 'none' : 'block';
  footer.style.display = todos.length === 0 ? 'none' : 'block';

  // Update count
  const countStr = activeCount === 1 ? '1 item left' : `${activeCount} items left`;
  todoCount.innerHTML = `<strong>${activeCount}</strong> ${activeCount === 1 ? 'item' : 'items'} left`;

  // Show/hide clear completed
  clearBtn.style.display = completedCount === 0 ? 'none' : 'block';

  // Update toggle-all
  toggleAll.checked = todos.length > 0 && activeCount === 0;
};

TodoMVCWorld.prototype.updateFilterLinks = function () {
  const hash = this.window.location.hash || '#/';
  const links = this.document.querySelectorAll('.filters a');
  for (const link of links) {
    link.classList.remove('selected');
    if (link.getAttribute('href') === hash) {
      link.classList.add('selected');
    }
  }
};

setWorldConstructor(TodoMVCWorld);

