  const label = editingLi.querySelector('label');
  const oldTitle = label ? label.textContent : '';

  const trimmed = newValue.trim();
  if (trimmed) {
    // Update todo in storage
    const todos = this.getTodos();
    const todo = todos.find(t => t.title === oldTitle);
